// Calibration recenter staging (added feature, v40).
//
// v39 asked the user to "return the head to center" between two calibration
// directions, but it moved the cursor to the screen center and re-zeroed the
// head pose IMMEDIATELY, while the user was still turned towards the corner
// they had just measured. Two things then happened:
//
//   1. The pose that got recorded as "facing the center" was the turned pose
//      (the corner pose), because the zero point was captured before the user
//      straightened up.
//   2. Straightening up afterwards looked like a large head movement, so the
//      cursor was pushed AWAY from the center by exactly that return swing.
//
// The next direction then started from "somewhere off center with a biased
// zero point", and the measured gain came out wrong ("after calibrating the
// cursor only moves within a small area"). The fix is to split the pause into
// three stages and let the user actually finish moving first:
//
//   waitHead - the cursor is FROZEN where it is and the panel asks the user to
//              straighten their head. The head's return swing therefore moves
//              nothing. As soon as the head has been still for a moment
//              (or the user confirms with a button / Space), go to:
//   glide    - the cursor glides from where it is to the screen center over a
//              short animation; the head pose is NOT used meanwhile.
//   ready    - the cursor is at the center and the pose the user is holding
//              RIGHT NOW has just become the new zero. The user confirms with
//              a mouth open, and only then does the next direction start.
//
// Pure logic, exported for testing (same pattern as auto-recenter.js): the
// frame loop owns the real cursor, the tilt neutral and the panel.

export const ARM_EPSILON = 0.004; // head movement that counts as "the user is turning back"
export const STILL_EPSILON = 0.0025; // per-frame head movement treated as "still"
export const STILL_HOLD_MS = 350; // head still for this long → it has returned
export const GLIDE_MS = 700; // cursor glide duration
export const STILL_FALLBACK_MS = 2000; // wait this long even if the head never moved
export const AUTO_ADVANCE_MS = 8000; // backstop: never wait for the head forever

const easeInOut = (t) => t * t * (3 - 2 * t); // smoothstep

export function createRecenterStage() {
	return {
		phase: "waitHead", // "waitHead" | "glide" | "ready"
		stillSince: null, // when the head became still (null = moving)
		armed: false, // the head has moved since the pause opened (i.e. turned back)
		glide: null, // { fromX, fromY, toX, toY, start }
		since: null, // when this stage was entered
	};
}

/**
 * One frame of the staged recenter pause.
 * @param state mutable state from createRecenterStage()
 * @param p {{
 *   movementX, movementY, // this frame's head movement (pre-sensitivity), 0 = still
 *   now, // performance.now()
 *   cursor, // {x, y} current cursor position
 *   center, // {x, y} screen center to glide to
 *   force, // true: the user said "my head is centered" (button / Space)
 *   stillHoldMs, glideMs, autoAdvanceMs, // optional overrides (tests)
 * }}
 * @returns {{
 *   phase, // the stage AFTER this frame
 *   x, y, // where the cursor should be this frame
 *   resetTilt, // true on the frame the glide lands: this pose is the new zero
 *   changed, // true when phase differs from the state's phase at entry
 * }}
 */
export function stepRecenter(state, {
	movementX = 0,
	movementY = 0,
	now,
	cursor = { x: 0, y: 0 },
	center = { x: 0, y: 0 },
	force = false,
	stillHoldMs = STILL_HOLD_MS,
	glideMs = GLIDE_MS,
	stillFallbackMs = STILL_FALLBACK_MS,
	autoAdvanceMs = AUTO_ADVANCE_MS,
} = {}) {
	const before = state.phase;
	const result = { phase: before, x: cursor.x, y: cursor.y, resetTilt: false, changed: false };
	if (state.since === null) {
		state.since = now;
	}

	const beginGlide = () => {
		state.glide = { fromX: cursor.x, fromY: cursor.y, toX: center.x, toY: center.y, start: now };
		state.phase = "glide";
		state.since = now;
		state.stillSince = null;
	};

	if (state.phase === "waitHead") {
		const magnitude = Math.hypot(movementX, movementY);
		if (magnitude >= ARM_EPSILON) {
			// The user IS moving: that is the return swing towards the neutral
			// pose. Only from here on does "still again" mean "the head is
			// back" - otherwise a head that is simply held still in the
			// corner would look like it had returned.
			state.armed = true;
			state.stillSince = null;
		} else if (magnitude < STILL_EPSILON && state.armed && state.stillSince === null) {
			state.stillSince = now;
		}
		const stillFor = state.stillSince === null ? 0 : now - state.stillSince;
		// Order of business:
		//  - the user may confirm with the button / Space at any time;
		//  - a return swing followed by a short stillness means the head is
		//    back, so the glide starts right away;
		//  - otherwise the pause lasts STILL_FALLBACK_MS (the "wait about two
		//    seconds" the panel promises) before the glide starts anyway, so a
		//    user who is already centered - or whose head never moved - isn't
		//    stuck;
		//  - AUTO_ADVANCE_MS is the last-resort backstop.
		if (
			force
			|| (state.armed && stillFor >= stillHoldMs)
			|| (now - state.since) >= stillFallbackMs
			|| (now - state.since) >= autoAdvanceMs
		) {
			beginGlide();
		}
	}

	if (state.phase === "glide") {
		const t = Math.min(1, (now - state.glide.start) / Math.max(1, glideMs));
		const ease = easeInOut(t);
		result.x = state.glide.fromX + (state.glide.toX - state.glide.fromX) * ease;
		result.y = state.glide.fromY + (state.glide.toY - state.glide.fromY) * ease;
		if (t >= 1) {
			result.x = state.glide.toX;
			result.y = state.glide.toY;
			result.resetTilt = true;
			state.glide = null;
			state.phase = "ready";
			state.since = now;
		}
	}

	result.phase = state.phase;
	result.changed = state.phase !== before;
	return result;
}

/**
 * Mark the stage as already done (cursor already at the center when the pause
 * opens): the caller should also reset the tilt neutral at that moment.
 */
export function markRecenterReady(state, now) {
	state.phase = "ready";
	state.since = now;
	state.stillSince = null;
	state.glide = null;
}
